using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;
namespace GearLab {
 public static class OverloadUiTests {public static int Run(string folder){Directory.CreateDirectory(folder);try{var t=CompoundReducer.Example();MaterialLibrary.ApplyDefaults(t);t.OutputLoad=new TrainOutputLoad{RadialForce=25,ForceOffset=30};t.Overload=new TrainOverloadSettings{Enabled=true};using(var form=new TrainDesignerForm(t)){form.ShowInTaskbar=false;form.Opacity=0;form.Show();Application.DoEvents();form.OverloadVerify(folder);form.WorkspaceApproveClose();form.Close();}File.WriteAllText(Path.Combine(folder,"overload-ui-results.json"),"{\"Passed\":true}");return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"overload-ui-error.txt"),ex.ToString());return 1;}}}
 public sealed partial class TrainDesignerForm {
  internal void OverloadVerify(string folder){Calculate();if(solution==null||!solution.Valid||solution.Strength==null)throw new Exception("Engineering UI solution missing");if(table.Rows.Count!=document.Stages.Count+1)throw new Exception("Totals row missing");if(materialAssignments.Rows.Count<5||strengthTable.Rows.Count==0||shaftTable.Rows.Count<8)throw new Exception("Engineering tables incomplete");viewer.Scene.SetResult(null,false);viewer.Scene.SetResult(solution.Scene,false);if(!viewer.Scene.Ready)throw new Exception(viewer.Scene.Error);overloadTorque.Value=1500;ApplyOverload();if(!overloadVisual.Enabled||!overloadVisual.Failed)throw new Exception("Overload slider did not trigger failure");double before=overloadVisual.OutputPhase;AdvanceOverload(1);if(overloadVisual.OutputPhase!=before)throw new Exception("Output did not stop");var output=solution.Scene.Model.Parts.First(p=>p.Id.EndsWith("_SH_OUTPUT_CARRIER"));var motion=PartMotion.Bind(solution.Scene,output);if(motion.At(1,0)!=motion.At(2,0))throw new Exception("Output pose still follows input");var input=solution.Scene.Model.Parts.First(p=>p.Id=="SH_INPUT_SHAFT");if(PartMotion.Bind(solution.Scene,input).At(1,0)==PartMotion.Bind(solution.Scene,input).At(2,0))throw new Exception("Input incorrectly stopped");var node=viewer.Scene.Nodes.First(n=>n.Part.Id==solution.Strength.WeakestPart);var brush=((System.Windows.Media.Media3D.DiffuseMaterial)node.Material).Brush as System.Windows.Media.SolidColorBrush;var error=UiPalette.Get("Error");if(brush==null||brush.Color.R!=error.R||brush.Color.G!=error.G)throw new Exception("Weak part not coloured with error palette");string beforeLanguage=Snapshot();var oldLanguage=AppSettings.Current.Language;var oldTheme=AppSettings.Current.Theme;try{AppSettings.Current.Language=GearLanguage.English;AppSettings.Apply(this);if(I18n.T("Нагрузки")!="Loads")throw new Exception("English load label missing");if(!System.ComponentModel.TypeDescriptor.GetProperties(materialEditor.SelectedObject)["Density"].DisplayName.Contains("Density"))throw new Exception("English material property missing");AppSettings.Current.Theme=GearTheme.Светлая;ApplyOverload();var lightBrush=((System.Windows.Media.Media3D.DiffuseMaterial)node.Material).Brush as System.Windows.Media.SolidColorBrush;if(lightBrush.Color.R!=UiPalette.Get("Error").R)throw new Exception("Light error palette missing");}finally{AppSettings.Current.Language=oldLanguage;AppSettings.Current.Theme=oldTheme;AppSettings.Apply(this);ApplyOverload();}if(Snapshot()!=beforeLanguage){File.WriteAllText(Path.Combine(folder,"before-language.json"),beforeLanguage);File.WriteAllText(Path.Combine(folder,"after-language.json"),Snapshot());throw new Exception("Language/theme change mutated train parameters");}using(var bitmap=new Bitmap(1000,650))using(var preview=Grid("Способ","Деталь","Предел, Н·м","Запас","Формула / примечание")){preview.Dock=DockStyle.None;preview.Size=bitmap.Size;preview.DefaultCellStyle.WrapMode=DataGridViewTriState.True;preview.RowTemplate.Height=58;foreach(DataGridViewRow row in strengthTable.Rows)preview.Rows.Add(row.Cells.Cast<DataGridViewCell>().Select(cell=>cell.Value).ToArray());AppSettings.Apply(preview);preview.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(Path.Combine(folder,"overload-table.png"));}using(var panel=new ShaftLoadPanel{Size=new Size(800,420),Solution=solution})using(var bitmap=new Bitmap(panel.Width,panel.Height)){panel.DrawToBitmap(bitmap,panel.ClientRectangle);bitmap.Save(Path.Combine(folder,"shaft-loads.png"));}viewer.Scene.HideHousing=true;viewer.Scene.RefreshVisibility();viewer.Scene.Root.Measure(new System.Windows.Size(1000,800));viewer.Scene.Root.Arrange(new System.Windows.Rect(0,0,1000,800));viewer.Scene.Fit();viewer.Present(2);viewer.Scene.SavePng(Path.Combine(folder,"overload-3d.png"),1000,800);document.Overload.ClutchEnabled=true;document.Overload.Friction=.2;document.Overload.TargetTorque=1.2;Calculate();if(solution==null||!solution.Valid||Math.Abs(solution.Strength.SpringForce.Value-200)>1e-8||!shaftTable.Rows.Cast<DataGridViewRow>().Any(row=>Convert.ToString(row.Cells[0].Value)=="Прижим муфты, Н"))throw new Exception("Calculated clutch force is not visible");document.SharedHousing.Wall=double.NaN;Changed();if(solution!=null||CaptureStage())throw new Exception("Invalid housing value was not blocked before history/export");document.SharedHousing.Wall=4;Changed();Calculate();if(solution==null||!solution.Valid)throw new Exception("Valid housing value did not recover the editor");}
 }
}
